SELECT
FROM spots s
INNER JOIN sub_categories sc ON sc.id = s.sub_category_id INNER JOIN categories c ON c.id = sc.category_id WHERE s.deleted_at IS NULL ORDER BY s.updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT
FROM spots s
LEFT JOIN sub_categories sc ON sc.id = s.sub_category_id LEFT JOIN categories c ON c.id = sc.category_id WHERE sc.category_id = #{categoryId} AND s.deleted_at IS NULL ORDER BY s.updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT
FROM spots s
LEFT JOIN sub_categories sc ON sc.id = s.sub_category_id LEFT JOIN categories c ON c.id = sc.category_id WHERE s.sub_category_id = #{subCategoryId} AND s.deleted_at IS NULL ORDER BY s.updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT
FROM spots s
LEFT JOIN sub_categories sc ON sc.id = s.sub_category_id LEFT JOIN categories c ON c.id = sc.category_id WHERE deleted_at IS NULL AND s.id != #{spotId}
AND (
keywords LIKE CONCAT('%', #{kw}, '%')
)
ORDER BY RANDOM() LIMIT #{limit}

SELECT
FROM spots s
LEFT JOIN sub_categories sc ON sc.id = s.sub_category_id LEFT JOIN categories c ON c.id = sc.category_id WHERE s.deleted_at IS NULL ORDER BY average_rating DESC NULLS LAST LIMIT #{limit}

SELECT
FROM spots s
LEFT JOIN sub_categories sc ON sc.id = s.sub_category_id LEFT JOIN categories c ON c.id = sc.category_id WHERE s.deleted_at IS NULL ORDER BY RANDOM() LIMIT #{limit}
